create or replace function private.has_church_branch_access(p_church_id uuid,p_branch_id uuid)
returns boolean language sql stable security definer set search_path=''
as $$
 select exists(select 1 from public.church_members cm where cm.church_id=p_church_id and cm.user_id=auth.uid() and cm.status='active' and (cm.role in ('owner','admin') or cm.branch_id is null or p_branch_id is null or cm.branch_id=p_branch_id));
$$;
revoke all on function private.has_church_branch_access(uuid,uuid) from public;
grant execute on function private.has_church_branch_access(uuid,uuid) to authenticated;

do $$ declare t text; begin
 foreach t in array array['church_branches','church_members','members','families','certificates','church_services','church_events','ministries','donations','expenses','church_assets'] loop
  execute format('create policy branch_scope_%I on public.%I as restrictive for all to authenticated using (private.has_church_branch_access(church_id,%s)) with check (private.has_church_branch_access(church_id,%s))',
   t,t,case when t='church_branches' then 'id' else 'branch_id' end,case when t='church_branches' then 'id' else 'branch_id' end);
 end loop;
end $$;

create policy branch_scope_family_relationships on public.family_relationships as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select f.branch_id from public.families f where f.id=family_relationships.family_id))) with check(private.has_church_branch_access(church_id,(select f.branch_id from public.families f where f.id=family_relationships.family_id)));
create policy branch_scope_member_documents on public.member_documents as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select m.branch_id from public.members m where m.id=member_documents.member_id))) with check(private.has_church_branch_access(church_id,(select m.branch_id from public.members m where m.id=member_documents.member_id)));
create policy branch_scope_attendance on public.attendance_records as restrictive for all to authenticated using(private.has_church_branch_access(church_id,coalesce((select s.branch_id from public.church_services s where s.id=attendance_records.service_id),(select e.branch_id from public.church_events e where e.id=attendance_records.event_id),(select m.branch_id from public.members m where m.id=attendance_records.member_id)))) with check(private.has_church_branch_access(church_id,coalesce((select s.branch_id from public.church_services s where s.id=attendance_records.service_id),(select e.branch_id from public.church_events e where e.id=attendance_records.event_id),(select m.branch_id from public.members m where m.id=attendance_records.member_id))));
create policy branch_scope_pastoral_requests on public.pastoral_requests as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select m.branch_id from public.members m where m.id=pastoral_requests.member_id))) with check(private.has_church_branch_access(church_id,(select m.branch_id from public.members m where m.id=pastoral_requests.member_id)));
create policy branch_scope_pastoral_followups on public.pastoral_followups as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select m.branch_id from public.pastoral_requests p join public.members m on m.id=p.member_id where p.id=pastoral_followups.request_id))) with check(private.has_church_branch_access(church_id,(select m.branch_id from public.pastoral_requests p join public.members m on m.id=p.member_id where p.id=pastoral_followups.request_id)));
create policy branch_scope_ministry_members on public.ministry_members as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select m.branch_id from public.ministries m where m.id=ministry_members.ministry_id))) with check(private.has_church_branch_access(church_id,(select m.branch_id from public.ministries m where m.id=ministry_members.ministry_id)));
create policy branch_scope_asset_maintenance on public.asset_maintenance as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select a.branch_id from public.church_assets a where a.id=asset_maintenance.asset_id))) with check(private.has_church_branch_access(church_id,(select a.branch_id from public.church_assets a where a.id=asset_maintenance.asset_id)));
create policy branch_scope_asset_depreciation on public.asset_depreciation_entries as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select a.branch_id from public.church_assets a where a.id=asset_depreciation_entries.asset_id))) with check(private.has_church_branch_access(church_id,(select a.branch_id from public.church_assets a where a.id=asset_depreciation_entries.asset_id)));
create policy branch_scope_donation_pledges on public.donation_pledges as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select m.branch_id from public.members m where m.id=donation_pledges.member_id))) with check(private.has_church_branch_access(church_id,(select m.branch_id from public.members m where m.id=donation_pledges.member_id)));
create policy branch_scope_certificate_attachments on public.certificate_attachments as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select c.branch_id from public.certificates c where c.id=certificate_attachments.certificate_id))) with check(private.has_church_branch_access(church_id,(select c.branch_id from public.certificates c where c.id=certificate_attachments.certificate_id)));
create policy branch_scope_certificate_history on public.certificate_history as restrictive for all to authenticated using(private.has_church_branch_access(church_id,(select c.branch_id from public.certificates c where c.id=certificate_history.certificate_id))) with check(private.has_church_branch_access(church_id,(select c.branch_id from public.certificates c where c.id=certificate_history.certificate_id)));

create policy branch_scope_journal_entries on public.journal_entries as restrictive for all to authenticated
using(private.has_church_branch_access(church_id,case when source_type='donation' then (select d.branch_id from public.donations d where d.id=source_id) when source_type='expense' then (select e.branch_id from public.expenses e where e.id=source_id) when source_type in ('asset_depreciation','asset_disposal') then (select a.branch_id from public.church_assets a where a.id=source_id) else null end))
with check(private.has_church_branch_access(church_id,case when source_type='donation' then (select d.branch_id from public.donations d where d.id=source_id) when source_type='expense' then (select e.branch_id from public.expenses e where e.id=source_id) when source_type in ('asset_depreciation','asset_disposal') then (select a.branch_id from public.church_assets a where a.id=source_id) else null end));
create policy branch_scope_journal_lines on public.journal_lines as restrictive for all to authenticated
using(private.has_church_branch_access(church_id,(select case when je.source_type='donation' then (select d.branch_id from public.donations d where d.id=je.source_id) when je.source_type='expense' then (select e.branch_id from public.expenses e where e.id=je.source_id) when je.source_type in ('asset_depreciation','asset_disposal') then (select a.branch_id from public.church_assets a where a.id=je.source_id) else null end from public.journal_entries je where je.id=journal_lines.journal_entry_id)))
with check(private.has_church_branch_access(church_id,(select case when je.source_type='donation' then (select d.branch_id from public.donations d where d.id=je.source_id) when je.source_type='expense' then (select e.branch_id from public.expenses e where e.id=je.source_id) when je.source_type in ('asset_depreciation','asset_disposal') then (select a.branch_id from public.church_assets a where a.id=je.source_id) else null end from public.journal_entries je where je.id=journal_lines.journal_entry_id)));

update public.church_members cm set branch_id=b.id from public.church_branches b where cm.church_id=b.church_id and b.is_head_office=true and cm.branch_id is null and cm.role not in ('owner','admin');
